mapper.insert:
INSERT INTO schedule ( trainno, depplacename, arrplacename, depplandtime, arrplandtime, booking_open_at, first_price, standard_price, status ) SELECT v.trainno, v.dep_node_id, v.arr_node_id, v.dep_time, v.arr_time, v.booking_open_at, v.first_price, v.standard_price, 'SCHEDULED' FROM ( VALUES
( CAST(#{s.trainno} AS integer), CAST(#{s.depNodeId} AS varchar), CAST(#{s.arrNodeId} AS varchar), CAST(#{s.depTime} AS timestamp), CAST(#{s.arrTime} AS timestamp), CAST(#{s.bookingOpenAt} AS timestamp), CAST(#{s.firstPrice} AS integer), CAST(#{s.standardPrice} AS integer), CAST(#{i} AS integer) )
) AS v(trainno, dep_node_id, arr_node_id, dep_time, arr_time, booking_open_at, first_price, standard_price, ord) WHERE NOT EXISTS ( SELECT 1 FROM schedule s WHERE s.trainno = v.trainno AND s.depplacename = v.dep_node_id AND s.arrplacename = v.arr_node_id AND s.depplandtime = v.dep_time ) ORDER BY v.ord
